import React, { useState, useEffect } from 'react';
import { Navigate } from 'react-router-dom';
import { useApp } from '../context/AppContext';
import { 
  Calendar, 
  Plus, 
  Clock, 
  MapPin, 
  Edit2, 
  Trash2, 
  X,
  ChevronLeft,
  ChevronRight,
  Bell
} from 'lucide-react';

interface ScheduleFormData {
  subject: string;
  room: string;
  startTime: string;
  endTime: string;
  dayOfWeek: number;
}

const Schedule: React.FC = () => {
  const { user, classSchedule, addClassSchedule, updateClassSchedule, deleteClassSchedule, darkMode } = useApp();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingClass, setEditingClass] = useState<string | null>(null);
  const [currentWeek, setCurrentWeek] = useState(new Date());
  const [formData, setFormData] = useState<ScheduleFormData>({
    subject: '',
    room: '',
    startTime: '',
    endTime: '',
    dayOfWeek: 1 // Monday
  });

  if (!user) {
    return <Navigate to="/login" replace />;
  }

  const weekDays = [
    { name: 'Sunday', short: 'Sun', value: 0 },
    { name: 'Monday', short: 'Mon', value: 1 },
    { name: 'Tuesday', short: 'Tue', value: 2 },
    { name: 'Wednesday', short: 'Wed', value: 3 },
    { name: 'Thursday', short: 'Thu', value: 4 },
    { name: 'Friday', short: 'Fri', value: 5 },
    { name: 'Saturday', short: 'Sat', value: 6 }
  ];

  const timeSlots = Array.from({ length: 24 }, (_, i) => {
    const hour = i;
    const time = hour.toString().padStart(2, '0') + ':00';
    return { hour, time };
  });

  // Get classes for each day
  const getClassesForDay = (dayOfWeek: number) => {
    return classSchedule
      .filter(cls => cls.dayOfWeek === dayOfWeek)
      .sort((a, b) => a.startTime.localeCompare(b.startTime));
  };

  // Check if current time is within class time
  const isCurrentClass = (startTime: string, endTime: string) => {
    const now = new Date();
    const currentTime = now.getHours() * 60 + now.getMinutes();
    const start = parseInt(startTime.split(':')[0]) * 60 + parseInt(startTime.split(':')[1]);
    const end = parseInt(endTime.split(':')[0]) * 60 + parseInt(endTime.split(':')[1]);
    return currentTime >= start && currentTime <= end;
  };

  // Get current day
  const getCurrentDay = () => {
    return new Date().getDay();
  };

  const resetForm = () => {
    setFormData({
      subject: '',
      room: '',
      startTime: '',
      endTime: '',
      dayOfWeek: 1
    });
    setEditingClass(null);
  };

  const openModal = (cls?: any) => {
    if (cls) {
      setEditingClass(cls.id);
      setFormData({
        subject: cls.subject,
        room: cls.room,
        startTime: cls.startTime,
        endTime: cls.endTime,
        dayOfWeek: cls.dayOfWeek
      });
    } else {
      resetForm();
    }
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    resetForm();
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.subject.trim() || !formData.room.trim() || !formData.startTime || !formData.endTime) {
      return;
    }

    // Validate time
    if (formData.startTime >= formData.endTime) {
      alert('End time must be after start time');
      return;
    }

    const scheduleData = {
      subject: formData.subject.trim(),
      room: formData.room.trim(),
      startTime: formData.startTime,
      endTime: formData.endTime,
      dayOfWeek: formData.dayOfWeek
    };

    if (editingClass) {
      updateClassSchedule(editingClass, scheduleData);
    } else {
      addClassSchedule(scheduleData);
    }

    closeModal();
  };

  const navigateWeek = (direction: 'prev' | 'next') => {
    const newWeek = new Date(currentWeek);
    if (direction === 'prev') {
      newWeek.setDate(newWeek.getDate() - 7);
    } else {
      newWeek.setDate(newWeek.getDate() + 7);
    }
    setCurrentWeek(newWeek);
  };

  const goToToday = () => {
    setCurrentWeek(new Date());
  };

  const getWeekDates = () => {
    const dates = [];
    const startOfWeek = new Date(currentWeek);
    const day = startOfWeek.getDay();
    const diff = startOfWeek.getDate() - day;
    startOfWeek.setDate(diff);

    for (let i = 0; i < 7; i++) {
      const date = new Date(startOfWeek);
      date.setDate(startOfWeek.getDate() + i);
      dates.push(date);
    }
    return dates;
  };

  const weekDates = getWeekDates();
  const currentDay = getCurrentDay();

  // Calculate statistics
  const stats = {
    totalClasses: classSchedule.length,
    todayClasses: getClassesForDay(currentDay).length,
    weekClasses: classSchedule.length,
    currentClass: classSchedule.filter(cls => 
      cls.dayOfWeek === currentDay && isCurrentClass(cls.startTime, cls.endTime)
    ).length
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            Class Schedule
          </h1>
          <p className="text-gray-600 dark:text-gray-300 mt-2">
            Manage your weekly timetable
          </p>
        </div>
        <button
          onClick={() => openModal()}
          className="btn-primary"
        >
          <Plus className="w-4 h-4 mr-2" />
          Add Class
        </button>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="card p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">Total Classes</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">{stats.totalClasses}</p>
            </div>
            <Calendar className="w-8 h-8 text-blue-500" />
          </div>
        </div>
        <div className="card p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">Today</p>
              <p className="text-2xl font-bold text-green-600">{stats.todayClasses}</p>
            </div>
            <Clock className="w-8 h-8 text-green-500" />
          </div>
        </div>
        <div className="card p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">This Week</p>
              <p className="text-2xl font-bold text-purple-600">{stats.weekClasses}</p>
            </div>
            <Calendar className="w-8 h-8 text-purple-500" />
          </div>
        </div>
        <div className="card p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">Now</p>
              <p className="text-2xl font-bold text-orange-600">{stats.currentClass}</p>
            </div>
            <Bell className="w-8 h-8 text-orange-500" />
          </div>
        </div>
      </div>

      {/* Week Navigation */}
      <div className="card p-4">
        <div className="flex items-center justify-between">
          <button
            onClick={navigateWeek.bind(null, 'prev')}
            className="p-2 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200"
          >
            <ChevronLeft className="w-5 h-5" />
          </button>

          <div className="text-center">
            <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
              Week of {weekDates[0].toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })}
            </h2>
            <button
              onClick={goToToday}
              className="text-sm text-primary-600 hover:text-primary-500 mt-1"
            >
              Go to Today
            </button>
          </div>

          <button
            onClick={navigateWeek.bind(null, 'next')}
            className="p-2 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200"
          >
            <ChevronRight className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* Weekly Schedule Grid */}
      <div className="card overflow-hidden">
        <div className="overflow-x-auto">
          <div className="min-w-[800px]">
            {/* Header */}
            <div className="grid grid-cols-8 border-b border-gray-200 dark:border-gray-700">
              <div className="p-3 text-sm font-medium text-gray-700 dark:text-gray-300">
                Time
              </div>
              {weekDays.map((day, index) => {
                const date = weekDates[index];
                const isToday = date.toDateString() === new Date().toDateString();
                const classesCount = getClassesForDay(day.value).length;

                return (
                  <div
                    key={day.value}
                    className={`p-3 text-center border-l border-gray-200 dark:border-gray-700 ${
                      isToday ? 'bg-primary-50 dark:bg-primary-900/20' : ''
                    }`}
                  >
                    <div className={`text-sm font-medium ${
                      isToday ? 'text-primary-700 dark:text-primary-300' : 'text-gray-700 dark:text-gray-300'
                    }`}>
                      {day.short}
                    </div>
                    <div className={`text-xs ${
                      isToday ? 'text-primary-600 dark:text-primary-400' : 'text-gray-500 dark:text-gray-400'
                    }`}>
                      {date.getDate()}
                    </div>
                    {classesCount > 0 && (
                      <div className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                        {classesCount} class{classesCount > 1 ? 'es' : ''}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>

            {/* Time Slots */}
            {timeSlots.map((slot) => (
              <div key={slot.hour} className="grid grid-cols-8 border-b border-gray-100 dark:border-gray-800">
                {/* Time Label */}
                <div className="p-3 text-sm text-gray-500 dark:text-gray-400 border-r border-gray-200 dark:border-gray-700">
                  {slot.time}
                </div>

                {/* Days */}
                {weekDays.map((day) => {
                  const dayClasses = getClassesForDay(day.value);
                  const currentClass = dayClasses.find(cls => 
                    isCurrentClass(cls.startTime, cls.endTime)
                  );

                  return (
                    <div
                      key={`${day.value}-${slot.hour}`}
                      className={`p-1 border-l border-gray-200 dark:border-gray-700 min-h-[60px] ${
                        currentClass ? 'bg-orange-50 dark:bg-orange-900/20' : ''
                      }`}
                    >
                      {dayClasses
                        .filter(cls => {
                          const startHour = parseInt(cls.startTime.split(':')[0]);
                          const endHour = parseInt(cls.endTime.split(':')[0]);
                          return slot.hour >= startHour && slot.hour < endHour;
                        })
                        .map(cls => {
                          const startHour = parseInt(cls.startTime.split(':')[0]);
                          const isStart = slot.hour === startHour;

                          if (!isStart) return null;

                          const duration = parseInt(cls.endTime.split(':')[0]) - startHour;

                          return (
                            <div
                              key={cls.id}
                              className={`p-2 rounded-md text-xs cursor-pointer transition-all hover:shadow-md ${
                                currentClass 
                                  ? 'bg-orange-200 dark:bg-orange-800 border-orange-300 dark:border-orange-700' 
                                  : 'bg-blue-100 dark:bg-blue-900/30 border-blue-200 dark:border-blue-800'
                              }`}
                              style={{ minHeight: `${duration * 60 - 8}px` }}
                              onClick={() => openModal(cls)}
                            >
                              <div className="font-medium text-gray-900 dark:text-white truncate">
                                {cls.subject}
                              </div>
                              <div className="text-gray-600 dark:text-gray-300 truncate">
                                {cls.startTime} - {cls.endTime}
                              </div>
                              <div className="flex items-center text-gray-500 dark:text-gray-400 mt-1">
                                <MapPin className="w-3 h-3 mr-1" />
                                {cls.room}
                              </div>
                              {currentClass && (
                                <div className="flex items-center text-orange-600 dark:text-orange-400 mt-1">
                                  <Bell className="w-3 h-3 mr-1" />
                                  Now
                                </div>
                              )}
                            </div>
                          );
                        })}
                    </div>
                  );
                })}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Today's Schedule (Mobile View) */}
      <div className="lg:hidden card p-4">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          Today's Classes
        </h3>
        <div className="space-y-3">
          {getClassesForDay(currentDay).length === 0 ? (
            <div className="text-center py-8">
              <Calendar className="w-12 h-12 text-gray-400 mx-auto mb-3" />
              <p className="text-gray-500 dark:text-gray-400">No classes today</p>
            </div>
          ) : (
            getClassesForDay(currentDay).map(cls => {
              const isCurrent = isCurrentClass(cls.startTime, cls.endTime);

              return (
                <div
                  key={cls.id}
                  className={`p-3 rounded-lg border cursor-pointer transition-all hover:shadow-md ${
                    isCurrent 
                      ? 'bg-orange-50 dark:bg-orange-900/20 border-orange-200 dark:border-orange-800' 
                      : 'bg-gray-50 dark:bg-gray-800 border-gray-200 dark:border-gray-700'
                  }`}
                  onClick={() => openModal(cls)}
                >
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <h4 className="font-medium text-gray-900 dark:text-white">
                        {cls.subject}
                      </h4>
                      <div className="flex items-center gap-3 mt-1">
                        <div className="flex items-center text-sm text-gray-600 dark:text-gray-300">
                          <Clock className="w-3 h-3 mr-1" />
                          {cls.startTime} - {cls.endTime}
                        </div>
                        <div className="flex items-center text-sm text-gray-600 dark:text-gray-300">
                          <MapPin className="w-3 h-3 mr-1" />
                          {cls.room}
                        </div>
                      </div>
                      {isCurrent && (
                        <div className="flex items-center text-orange-600 dark:text-orange-400 mt-2">
                          <Bell className="w-3 h-3 mr-1" />
                          Currently in class
                        </div>
                      )}
                    </div>
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        openModal(cls);
                      }}
                      className="p-2 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200"
                    >
                      <Edit2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>

      {/* Add/Edit Class Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="card w-full max-w-md">
            <div className="flex items-center justify-between p-6 border-b border-gray-200 dark:border-gray-700">
              <h2 className="text-xl font-semibold text-gray-900 dark:text-white">
                {editingClass ? 'Edit Class' : 'Add New Class'}
              </h2>
              <button
                onClick={closeModal}
                className="p-2 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              {/* Subject */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Subject *
                </label>
                <input
                  type="text"
                  required
                  value={formData.subject}
                  onChange={(e) => setFormData({ ...formData, subject: e.target.value })}
                  className="input w-full"
                  placeholder="Enter subject name"
                />
              </div>

              {/* Room */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Room *
                </label>
                <input
                  type="text"
                  required
                  value={formData.room}
                  onChange={(e) => setFormData({ ...formData, room: e.target.value })}
                  className="input w-full"
                  placeholder="Enter room number"
                />
              </div>

              {/* Day of Week */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Day of Week *
                </label>
                <select
                  value={formData.dayOfWeek}
                  onChange={(e) => setFormData({ ...formData, dayOfWeek: parseInt(e.target.value) })}
                  className="input w-full"
                >
                  {weekDays.map(day => (
                    <option key={day.value} value={day.value}>
                      {day.name}
                    </option>
                  ))}
                </select>
              </div>

              {/* Time */}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                    Start Time *
                  </label>
                  <input
                    type="time"
                    required
                    value={formData.startTime}
                    onChange={(e) => setFormData({ ...formData, startTime: e.target.value })}
                    className="input w-full"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                    End Time *
                  </label>
                  <input
                    type="time"
                    required
                    value={formData.endTime}
                    onChange={(e) => setFormData({ ...formData, endTime: e.target.value })}
                    className="input w-full"
                  />
                </div>
              </div>

              {/* Actions */}
              <div className="flex gap-3 pt-4">
                <button
                  type="button"
                  onClick={closeModal}
                  className="btn-secondary flex-1"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="btn-primary flex-1"
                >
                  {editingClass ? 'Update Class' : 'Add Class'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Schedule;
